using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using DBCD.Providers;
using MySqlConnector;
namespace WoWItemEditor;
internal sealed record RecoveryEntry(ContentOperation Operation,bool Legacy=false,int Build=0);
internal sealed record RecoveryRow(string Name,string Kind,int EntityId,string Status);
internal sealed record ActiveRecoveryPlan(string Guard,List<RecoveryRow> Rows,List<string> Notes,int Items);
internal static class ActiveChangeRecovery
{
    internal static string Batches=>AppSettings.Current.BackupDatabase+".item_editor_recovery_batches";
    private static ItemSnapshot Decode(string json)=>JsonSerializer.Deserialize<ItemSnapshot>(json)??throw new InvalidOperationException("Invalid retained snapshot.");
    private static ContentScope Scope(ContentOperation op)=>JsonSerializer.Deserialize<ContentScope>(op.Scope)??throw new InvalidOperationException("Invalid retained scope.");
    private static int N(IReadOnlyDictionary<string,string?> row,string key)=>int.TryParse(row.GetValueOrDefault(key),out int n)?n:0;
    private static string Hash(string text)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));
    private static string NativeStamp()=>Hash(string.Join("/",Directory.EnumerateFiles(CatalogRepository.Db2Folder,"*.db2").Order().Select(p=>{var f=new FileInfo(p);return f.Name+":"+f.Length+":"+f.LastWriteTimeUtc.Ticks;})));
    internal static async Task Initialize(MySqlConnection db){await ContentEditing.InitializeAsync(db);using var cmd=new MySqlCommand($"CREATE TABLE IF NOT EXISTS {Batches}(BatchId CHAR(36) PRIMARY KEY,CreatedUtc DATETIME(6) NOT NULL,Actor VARCHAR(255) NOT NULL,OperationCount INT NOT NULL,BeforeJson LONGTEXT NOT NULL,AfterJson LONGTEXT NOT NULL,RetainedMetadataJson LONGTEXT NOT NULL,NotesJson LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",db);await cmd.ExecuteNonQueryAsync();}
    internal static async Task<ActiveRecoveryPlan> Prepare(Action<string>? progress=null)
    {
        using var db=await DatabaseConnection.OpenAsync(CatalogRepository.Database);await Initialize(db);
        using(var gate=new MySqlCommand("SELECT GET_LOCK('anocore_studio_forge',8)",db))if(Convert.ToInt32(await gate.ExecuteScalarAsync())!=1)throw new InvalidOperationException("Another editor is saving; retry shortly.");
        try{using var tx=await db.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);try{return await Run(db,tx,null,false,progress);}finally{await tx.RollbackAsync();}}
        finally{using var release=new MySqlCommand("SELECT RELEASE_LOCK('anocore_studio_forge')",db);await release.ExecuteScalarAsync();}
    }
    internal static Task<ActiveRecoveryPlan> Apply(ActiveRecoveryPlan plan,Action<string>? progress=null)=>ContentEditing.Transaction(async(db,tx)=>await Run(db,tx,plan.Guard,true,progress));
    private static async Task<List<RecoveryEntry>> Read(MySqlConnection db,MySqlTransaction tx)
    {
        var entries=new List<RecoveryEntry>();foreach(var row in await WorldDrops.Query(db,tx,$"SELECT * FROM {ContentEditing.Operations} WHERE IsActive=1 ORDER BY RecordedUtc,OperationId FOR UPDATE")){var op=new ContentOperation(row["OperationId"]!,row["Kind"]!,N(row,"EntityId"),row["Name"]!,true,row["IsHidden"]=="1",N(row,"Version"),row["BeforeJson"]!,row["AfterJson"]!,row["ExpectedJson"]!,row["ScopeJson"]!,row["Fingerprint"]!,row["RecordedUtc"]!);entries.Add(new(op));}
        foreach(var row in await WorldDrops.Query(db,tx,$"SELECT * FROM {HistoryActions.Archive} WHERE IsActive=1 ORDER BY UpdatedUtc,ItemId,PayloadBuild FOR UPDATE")){int id=N(row,"ItemId"),build=N(row,"PayloadBuild");string json=row["ModifiedJson"]!;var item=HotfixHistory.SnapshotItem(json,id);var scope=new ContentScope("Item",id,[id],[],[id],[]);var op=new ContentOperation(row["LastEventId"]!,"Item",id,item?.Name??$"Item {id}",true,false,N(row,"Version"),row["BaselineJson"]!,json,row["ExpectedJson"]!,JsonSerializer.Serialize(scope),"",row["UpdatedUtc"]!);entries.Add(new(op,true,build));}
        return entries.OrderBy(e=>DateTime.Parse(e.Operation.RecordedUtc,CultureInfo.InvariantCulture)).ThenBy(e=>e.Operation.Id,StringComparer.Ordinal).ToList();
    }
    private sealed class Checks
    {
        private readonly DBCD.DBCD reader=new(new FilesystemDBCProvider(CatalogRepository.Db2Folder),new GithubDBDProvider(true));
        private readonly Dictionary<string,HashSet<string>> schemas=[];
        internal async Task Rows(MySqlConnection db,MySqlTransaction tx,string table,IEnumerable<Dictionary<string,string?>> rows){var list=rows.ToList();if(list.Count==0)return;if(!schemas.TryGetValue(table,out var columns)){string[] parts=table.Split('.');string schema=parts.Length==2?parts[0]:CatalogRepository.Database,name=parts[^1];var metadata=await WorldDrops.Query(db,tx,$"SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='{schema}' AND TABLE_NAME='{name}'");columns=metadata.Select(r=>r["COLUMN_NAME"]!).ToHashSet(StringComparer.OrdinalIgnoreCase);schemas[table]=columns;var engine=await WorldDrops.Query(db,tx,$"SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA='{schema}' AND TABLE_NAME='{name}'");if(engine.Count!=1||engine[0]["ENGINE"]!="InnoDB")throw new InvalidOperationException(table+" must exist and support transactions.");}foreach(var row in list)if(!columns.SetEquals(row.Keys))throw new InvalidOperationException($"The saved {table} payload has a different schema after the upgrade. A field migration is needed; no recovery was committed.");}
        internal async Task NoNativeCollision(string dbc,IEnumerable<int> values){var ids=values.Where(id=>id>0).ToHashSet();if(ids.Count==0)return;string file=Path.Combine(CatalogRepository.Db2Folder,dbc+".db2");using(var stream=File.OpenRead(file)){var header=new byte[168];stream.ReadExactly(header);if(ids.All(id=>(uint)id>BitConverter.ToUInt32(header,164)))return;}var native=await Task.Run(()=>TooltipData.LoadTable(reader,dbc,r=>ids.Contains(TooltipData.Number(r,"ID"))));if(native.Count>0)throw new InvalidOperationException($"Upgrade ID collision: {dbc} now has native records using custom IDs {string.Join(", ",native.Keys.Take(8))}. They need remapping before recovery.");}
        internal async Task<CloneScope> Clone(CloneScope copy){foreach(var (table,ids) in copy.Records){if(!ItemCloning.Tables.TryGetValue(table,out string? dbc))throw new InvalidOperationException("Unknown clone table.");await NoNativeCollision(dbc,ids);}return copy with{Fingerprint=ItemCloning.Fingerprint()};}
        internal async Task<BonusScope?> Bonus(BonusScope? bonus,ItemSnapshot target){if(bonus is null)return null;foreach(var table in bonus.Tables){if(!System.Text.RegularExpressions.Regex.IsMatch(table.Sql,"^spell_[a-z0-9_]+$")||!System.Text.RegularExpressions.Regex.IsMatch(table.Dbc,"^[A-Za-z0-9]+$"))throw new InvalidOperationException("Invalid saved spell table.");var rows=target.Tables["bonus_"+table.Sql].Where(r=>bonus.OwnedSpells.Contains(N(r,table.ParentSpell?"SpellID":"ID"))).ToArray();await NoNativeCollision(table.Dbc,rows.Select(r=>N(r,"ID")));}await NoNativeCollision("Spell",bonus.OwnedSpells);return bonus with{Fingerprint=BonusSpells.Fingerprint(bonus.Tables)};}
        internal async Task<ContentScope> Normalize(ContentScope scope,ItemSnapshot target){if(scope.Kind is not ("Item" or "ItemDrops" or "Clone" or "Set" or "Proc" or "NewSet" or "SetMembers"))throw new InvalidOperationException("Unsupported history kind "+scope.Kind);var copy=scope.CopyScope is null?null:await Clone(scope.CopyScope);var creation=scope.Creation;if(creation is not null){await NoNativeCollision("ItemSet",[creation.SetId]);await NoNativeCollision("ItemSetSpell",creation.Bonuses);var copies=new Dictionary<int,CloneScope>();foreach(var (id,part) in creation.Copies)copies[id]=await Clone(part);creation=creation with{Copies=copies,PrivateBonuses=await Bonus(creation.PrivateBonuses,target)};}if(scope.Kind=="Set")await NoNativeCollision("ItemSetSpell",scope.RowIds.Except(scope.NativeRowIds));if(scope.Kind=="Proc"){await NoNativeCollision("ItemXItemEffect",scope.RowIds.Except(scope.NativeRowIds));await NoNativeCollision("ItemEffect",scope.EffectIds.Except(scope.NativeEffectIds));}return scope with{CopyScope=copy,Creation=creation,Bonus=await Bonus(scope.Bonus,target),ItemFingerprint=scope.ItemFingerprint is null?null:ItemEditing.IdentityFingerprint()};}
        internal async Task ValidateRows(MySqlConnection db,MySqlTransaction tx,ContentScope scope,ItemSnapshot target){foreach(var (key,rows) in target.Tables){string? table=ContentEditing.Tables.ContainsKey(key)?key:null;if(scope.Kind is "Proc"&&key is "item_sparse" or "item" or "item_set")table=null;if(scope.Kind=="Set"&&key=="item_set")table=null;if(key is "new_set")table="item_set";if(key is "new_set_bonuses")table="item_set_spell";if(key.StartsWith("piece_")){string suffix=key[(key.IndexOf('_',6)+1)..];if(ItemCloning.Tables.ContainsKey(suffix))table=suffix;}if(key.StartsWith("bonus_spell_"))table=key[6..];if(key=="bonus_blob")table="hotfix_blob";if(key=="bonus_proc")table=AppSettings.Current.WorldDatabase+".spell_proc";if(table is not null)await Rows(db,tx,table,rows);}}
    }
    private static async Task<HashSet<int>> RequiredSpells(MySqlConnection db,MySqlTransaction tx,List<RecoveryEntry> entries)
    {
        var bindings=new Dictionary<string,Dictionary<int,int>>();foreach(var table in new[]{"item_set_spell","item_effect","item_x_item_effect"}){var rows=(await HotfixReader.LoadAsync(db,table,TooltipData.Hash(ContentEditing.Tables[table]),tx)).ActiveRows;bindings[table]=rows.ToDictionary(p=>p.Key,p=>TooltipData.Number(p.Value,table=="item_x_item_effect"?"ItemEffectID":"SpellID"));}
        foreach(var entry in entries){var snapshot=Decode(entry.Operation.After);foreach(var (alias,payload) in snapshot.Tables){string table=alias,prefix="";if(alias=="new_set_bonuses")table="item_set_spell";else if(alias.StartsWith("piece_")){int split=alias.IndexOf('_',6);prefix=alias[..(split+1)];table=alias[(split+1)..];}if(!bindings.ContainsKey(table))continue;string registrationKey=alias=="new_set_bonuses"?"new_set_registrations":prefix+"hotfix_data";var registrations=snapshot.Tables.GetValueOrDefault(registrationKey)??[];uint hash=TooltipData.Hash(ContentEditing.Tables[table]);foreach(var registration in registrations.Where(r=>r.GetValueOrDefault("TableHash")==hash.ToString(CultureInfo.InvariantCulture)).GroupBy(r=>N(r,"RecordId")).Select(g=>g.OrderBy(r=>long.Parse(r["Id"]!)).ThenBy(r=>long.Parse(r["UniqueId"]!)).Last())){int id=N(registration,"RecordId");var row=payload.Where(r=>N(r,"ID")==id).OrderBy(r=>N(r,"VerifiedBuild")==0?0:1).ThenByDescending(r=>N(r,"VerifiedBuild")).FirstOrDefault();if(N(registration,"Status")==1&&row is not null)bindings[table][id]=N(row,table=="item_x_item_effect"?"ItemEffectID":"SpellID");else bindings[table].Remove(id);}}}
        return bindings["item_set_spell"].Values.Concat(bindings["item_x_item_effect"].Values.Where(bindings["item_effect"].ContainsKey).Select(id=>bindings["item_effect"][id])).ToHashSet();
    }
    private static ContentScope ReplayScope(ContentScope scope,ItemSnapshot target,HashSet<int> required,List<string> notes)
    {
        BonusScope? Filter(BonusScope? bonus){if(bonus is null||bonus.OwnedSpells.Any(required.Contains))return bonus;foreach(var row in target.Tables["bonus_spell_effect"].Where(r=>bonus.OwnedSpells.Contains(N(r,"SpellID")))){var fields=row.ToDictionary(p=>p.Key,p=>p.Value??"",StringComparer.OrdinalIgnoreCase);if(bonus.EditedEffects?.Contains(N(row,"ID"))==true||bonus.EditedEffects is null&&BonusSpells.Editable(fields)){try{BonusValueRules.Validate(fields,fields.GetValueOrDefault("EffectBasePointsF")??fields.GetValueOrDefault("EffectBasePoints")??"0");}catch(InvalidOperationException){notes.Add($"Historical private spell version {string.Join(", ",bonus.OwnedSpells)} is superseded and exceeds current value limits. It is retained in history and is not activated; current final assignments use a later version.");return bonus with{OwnedSpells=[]};}}}return bonus;}
        return scope with{Bonus=Filter(scope.Bonus),Creation=scope.Creation is null?null:scope.Creation with{PrivateBonuses=Filter(scope.Creation.PrivateBonuses)}};
    }
    private static async Task CheckAllocatedSql(MySqlConnection db,MySqlTransaction tx,List<RecoveryEntry> entries,List<ContentScope> scopes)
    {
        var owned=new Dictionary<string,HashSet<int>>();
        void Add(string table,IEnumerable<int> ids){if(!owned.TryGetValue(table,out var set))owned[table]=set=[];set.UnionWith(ids);}
        void Copy(CloneScope? copy){if(copy is not null)foreach(var pair in copy.Records)Add(pair.Key,pair.Value);}
        foreach(var scope in scopes){Copy(scope.CopyScope);if(scope.Kind=="Set")Add("item_set_spell",scope.RowIds.Except(scope.NativeRowIds));if(scope.Kind=="Proc"){Add("item_effect",scope.EffectIds.Except(scope.NativeEffectIds));Add("item_x_item_effect",scope.RowIds.Except(scope.NativeRowIds));}if(scope.Creation is {} creation){Add("item_set",[creation.SetId]);Add("item_set_spell",creation.Bonuses);foreach(var copy in creation.Copies.Values)Copy(copy);}foreach(var bonus in new[]{scope.Bonus,scope.Creation?.PrivateBonuses}.OfType<BonusScope>())foreach(var table in bonus.Tables)foreach(var json in new[]{entries[scopes.IndexOf(scope)].Operation.After})Add(table.Sql,Decode(json).Tables["bonus_"+table.Sql].Where(r=>bonus.OwnedSpells.Contains(N(r,table.ParentSpell?"SpellID":"ID"))).Select(r=>N(r,"ID")));}
        string Canon(Dictionary<string,string?> row)=>JsonSerializer.Serialize(row.Where(p=>p.Key!="VerifiedBuild").OrderBy(p=>p.Key).ToDictionary(p=>p.Key,p=>p.Value));
        foreach(var (table,ids) in owned){if(ids.Count==0)continue;var known=new HashSet<string>();foreach(var entry in entries)foreach(string json in new[]{entry.Operation.Before,entry.Operation.After,entry.Operation.Expected})foreach(var (alias,rows) in Decode(json).Tables)if(alias==table||alias=="bonus_"+table||alias=="new_set"&&table=="item_set"||alias=="new_set_bonuses"&&table=="item_set_spell"||alias.StartsWith("piece_")&&alias.EndsWith("_"+table))foreach(var row in rows.Where(r=>ids.Contains(N(r,"ID"))))known.Add(Canon(row));foreach(var row in await WorldDrops.Query(db,tx,$"SELECT * FROM {table} WHERE ID IN({WorldDrops.Ids(ids)}) FOR UPDATE"))if(!known.Contains(Canon(row)))throw new InvalidOperationException($"Custom ID collision: {table} {row["ID"]} contains an unrecognized live definition. Resolve or remap it before recovery.");}
    }
    private static ItemSnapshot GuardSnapshot(ItemSnapshot snapshot)=>snapshot with{Tables=snapshot.Tables.Where(p=>!p.Key.EndsWith("owned_instances")&&!p.Key.EndsWith("void_instances")).ToDictionary(p=>p.Key,p=>p.Value)};
    internal static async Task<ActiveRecoveryPlan> Run(MySqlConnection db,MySqlTransaction tx,string? guard,bool commit,Action<string>? progress=null)
    {
        var entries=await Read(db,tx);if(entries.Count==0)throw new InvalidOperationException("There are no retained active changes to recover.");var checks=new Checks();var scopes=new List<ContentScope>();var targets=new List<ItemSnapshot>();var initial=new List<ItemSnapshot>();var notes=new List<string>();string stamp=NativeStamp();
        for(int n=0;n<entries.Count;n++){var op=entries[n].Operation;progress?.Invoke($"Checking {n+1}/{entries.Count}: {op.Name}");try{var target=Decode(op.After);var scope=await checks.Normalize(Scope(op),target);await checks.ValidateRows(db,tx,scope,target);scopes.Add(scope);targets.Add(target);initial.Add(await ContentEditing.CaptureAsync(db,tx,scope,true));}catch(Exception ex){throw new InvalidOperationException($"Cannot recover {op.Name} ({op.Kind} {op.EntityId}): {ex.Message}",ex);}}
        await CheckAllocatedSql(db,tx,entries,scopes);
        WorldDropCatalog? world=null;if(scopes.Any(s=>s.Creation?.Drops is not null||s.Drops is not null)){progress?.Invoke("Checking the upgraded world drop definitions...");world=await WorldDropCatalog.LoadAsync(db,tx);}
        string currentGuard=Hash(stamp+world?.Fingerprint+world?.BossFingerprint+JsonSerializer.Serialize(entries)+string.Join("\n",initial.Select(s=>HistoryActions.Canonical(GuardSnapshot(s)))));if(guard is not null&&guard!=currentGuard)throw new InvalidOperationException("Active history, live data or installed definitions changed after the review. Prepare recovery again.");
        var required=await RequiredSpells(db,tx,entries);var post=new List<ItemSnapshot>();var finalItems=new Dictionary<int,CatalogItem>();foreach(var target in targets){foreach(var (key,rows) in target.Tables.Where(p=>p.Key=="item_sparse"||p.Key.StartsWith("piece_")&&p.Key.EndsWith("_item_sparse")))foreach(var row in rows){int id=N(row,"ID");var prefix=key=="item_sparse"?"":key[..^"item_sparse".Length];var part=new ItemSnapshot(target.Tables.Where(p=>p.Key.StartsWith(prefix)).ToDictionary(p=>p.Key[prefix.Length..],p=>p.Value));var item=HotfixHistory.SnapshotItem(HistoryActions.Serialize(part),id);if(item is not null)finalItems[id]=item;}}
        var rowsResult=new List<RecoveryRow>();
        for(int n=0;n<entries.Count;n++){var entry=entries[n];var op=entry.Operation;var scope=scopes[n];var target=targets[n];progress?.Invoke($"Replaying {n+1}/{entries.Count}: {op.Name}");try{
            var drops=scope.Creation?.Drops??scope.Drops;if(drops is not null&&target.Tables.TryGetValue("world_drop_policy",out var policies)&&policies.Count>0){world??=await WorldDropCatalog.LoadAsync(db,tx);foreach(var policy in policies){var old=JsonSerializer.Deserialize<DropPlan>(policy["PlanJson"]!)!;if(old.InputFingerprint==(old.Mode=="Boss"?world.BossFingerprint:world.Fingerprint))continue;int itemId=N(policy,"ItemId");if(!finalItems.TryGetValue(itemId,out var item))throw new InvalidOperationException("Cannot resolve the final item for drop recovery.");var rebuilt=WorldDrops.Replan(world,item,old);await WorldDrops.Apply(db,tx,itemId,rebuilt,item.Name);notes.Add($"{item.Name}: drop eligibility rebuilt for the upgraded world; {rebuilt.Summary}.");}var captured=await WorldDrops.Capture(db,tx,drops);foreach(var policy in policies){int item=N(policy,"ItemId");var old=JsonSerializer.Deserialize<DropPlan>(policy["PlanJson"]!)!;if(old.InputFingerprint==(old.Mode=="Boss"?world.BossFingerprint:world.Fingerprint))continue;target.Tables["world_loot"].RemoveAll(r=>N(r,"Item")==item);target.Tables["world_loot"].AddRange(captured["world_loot"].Where(r=>N(r,"Item")==item));}target.Tables["world_drop_policy"]=policies.Select(p=>{var old=JsonSerializer.Deserialize<DropPlan>(p["PlanJson"]!)!;return old.InputFingerprint==(old.Mode=="Boss"?world.BossFingerprint:world.Fingerprint)?p:captured["world_drop_policy"].Single(r=>r["ItemId"]==p["ItemId"]);}).ToList();}
            if(entry.Legacy){using(var clear=new MySqlCommand($"DELETE FROM item_sparse WHERE ID={op.EntityId}",db,tx))await clear.ExecuteNonQueryAsync();foreach(var row in target.Tables.GetValueOrDefault("item_sparse")??[]){await ContentEditing.Upsert(db,tx,"item_sparse",row);}await ContentEditing.Register(db,tx,"item_sparse",op.EntityId,1);}else await ContentEditing.RestoreRetained(db,tx,ReplayScope(scope,target,required,notes),Decode(op.Before),target,target);
            var result=(await ContentEditing.CaptureAsync(db,tx,scope,true)) with{OriginalItem=target.OriginalItem,ContentRows=target.ContentRows};post.Add(result);rowsResult.Add(new(op.Name,op.Kind,op.EntityId,"Ready"));
        }catch(Exception ex){throw new InvalidOperationException($"Recovery blocked at {op.Name} ({op.Kind} {op.EntityId}): {ex.Message}. Nothing was committed.",ex);}}
        progress?.Invoke("Validating the complete recovered item state…");await ValidateFinal(db,tx,scopes);
        if(NativeStamp()!=stamp)throw new InvalidOperationException("Installed client definitions changed during recovery. Retry after the upgrade finishes.");
        if(commit){string batch=Guid.NewGuid().ToString();using(var backup=new MySqlCommand($"INSERT INTO {Batches}(BatchId,CreatedUtc,Actor,OperationCount,BeforeJson,AfterJson,RetainedMetadataJson,NotesJson) VALUES(@id,UTC_TIMESTAMP(6),@actor,@count,@before,@after,@metadata,@notes)",db,tx)){backup.Parameters.AddWithValue("@id",batch);backup.Parameters.AddWithValue("@actor",Environment.UserDomainName+"\\"+Environment.UserName);backup.Parameters.AddWithValue("@count",entries.Count);backup.Parameters.AddWithValue("@before",JsonSerializer.Serialize(initial));backup.Parameters.AddWithValue("@after",JsonSerializer.Serialize(post));backup.Parameters.AddWithValue("@metadata",JsonSerializer.Serialize(entries));backup.Parameters.AddWithValue("@notes",JsonSerializer.Serialize(notes));await backup.ExecuteNonQueryAsync();}
            for(int n=0;n<entries.Count;n++){var entry=entries[n];var op=entry.Operation;string json=HistoryActions.Serialize(targets[n]);using var update=new MySqlCommand(entry.Legacy?$"UPDATE {HistoryActions.Archive} SET Version=Version+1,ModifiedJson=@after,ExpectedJson=@expected,UpdatedUtc=UTC_TIMESTAMP(6) WHERE ItemId=@entity AND PayloadBuild=@build AND IsActive=1 AND Version=@version":$"UPDATE {ContentEditing.Operations} SET Version=Version+1,AfterJson=@after,ExpectedJson=@expected,ScopeJson=@scope,Fingerprint=@fingerprint WHERE OperationId=@op AND IsActive=1 AND Version=@version",db,tx);update.Parameters.AddWithValue("@after",json);update.Parameters.AddWithValue("@expected",HistoryActions.Serialize(post[n]));update.Parameters.AddWithValue("@scope",JsonSerializer.Serialize(scopes[n]));update.Parameters.AddWithValue("@fingerprint",ContentEditing.Fingerprint());update.Parameters.AddWithValue("@op",op.Id);update.Parameters.AddWithValue("@entity",op.EntityId);update.Parameters.AddWithValue("@build",entry.Build);update.Parameters.AddWithValue("@version",op.Version);if(await update.ExecuteNonQueryAsync()!=1)throw new InvalidOperationException("History changed during recovery.");await ContentEditing.Audit(db,tx,scopes[n],"Recover active edit",op.Name,batch,initial[n],post[n]);}
            notes.Add("Recovery batch "+batch+" retains the previous live snapshots and original history payloads in the backup database.");}
        notes.Insert(0,"All retained active changes are included, regardless of history search/filter settings. Inactive changes are excluded. Saved definitions replace affected live definitions. New hotfix registrations are generated; active flags are preserved. Restart the worldserver after applying.");return new(currentGuard,rowsResult,notes,finalItems.Count);
    }
    internal static async Task ValidateFinal(MySqlConnection db,MySqlTransaction tx,List<ContentScope> scopes)
    {
        var ids=scopes.Where(s=>s.Kind is "Item" or "ItemDrops" or "Clone" or "Proc").Select(s=>s.EntityId).Concat(scopes.Where(s=>s.Creation is not null).SelectMany(s=>s.Creation!.Copies.Keys)).Distinct().ToArray();var combined=new ItemSnapshot(new(){["item_sparse"]=[],["item"]=[]});foreach(int id in ids){var current=await HistoryActions.CaptureAsync(db,tx,id,true);combined.Tables["item_sparse"].AddRange(current.Tables["item_sparse"]);combined.Tables["item"].AddRange(current.Tables["item"]);}await ItemSaveSafety.ValidateSnapshot(db,tx,combined);
        var reader=new DBCD.DBCD(new FilesystemDBCProvider(CatalogRepository.Db2Folder),new GithubDBDProvider(true));var effects=await Task.Run(()=>TooltipData.LoadTable(reader,"ItemEffect"));await TooltipData.Overlay(db,"item_effect","ItemEffect",effects,tx);var spells=await Task.Run(()=>TooltipData.LoadTable(reader,"SpellName"));await TooltipData.Overlay(db,"spell_name","SpellName",spells,tx);var sets=await Task.Run(()=>TooltipData.LoadTable(reader,"ItemSet"));await TooltipData.Overlay(db,"item_set","ItemSet",sets,tx);
        var links=(await HotfixReader.LoadAsync(db,"item_x_item_effect",TooltipData.Hash("ItemXItemEffect"),tx)).ActiveRows.Values.Where(r=>ids.Contains(TooltipData.Number(r,"ItemID")));foreach(var row in links)if(!effects.ContainsKey(TooltipData.Number(row,"ItemEffectID")))throw new InvalidOperationException($"Recovered item {row["ItemID"]} references missing item effect {row["ItemEffectID"]}.");
        foreach(var row in combined.Tables["item_sparse"])if(N(row,"ItemSet")>0&&!sets.ContainsKey(N(row,"ItemSet")))throw new InvalidOperationException($"Recovered item {row["ID"]} references missing set {row["ItemSet"]}.");
        var setIds=scopes.Where(s=>s.Kind=="Set").Select(s=>s.EntityId).Concat(scopes.Where(s=>s.Creation is not null).Select(s=>s.Creation!.SetId));foreach(var row in (await HotfixReader.LoadAsync(db,"item_set_spell",TooltipData.Hash("ItemSetSpell"),tx)).ActiveRows.Values.Where(r=>setIds.Contains(TooltipData.Number(r,"ItemSetID"))))if(!spells.ContainsKey(TooltipData.Number(row,"SpellID")))throw new InvalidOperationException($"Recovered set bonus references missing spell {row["SpellID"]}.");foreach(var effect in effects.Values.Where(r=>scopes.SelectMany(s=>s.EffectIds).Contains(TooltipData.Number(r,"ID"))))if(!spells.ContainsKey(TooltipData.Number(effect,"SpellID")))throw new InvalidOperationException("Recovered proc references a missing spell.");
    }
}
